describe("Fixed-layout EPUB detection", function()
    local DocumentRegistry
    -- Fixtures live in the test-data submodule (spec/front/unit/data -> test/).
    -- They are generated by:
    --   base/thirdparty/kpvcrlib/crengine/tests/make_fixedlayout_test_epub.py
    local DATA = "spec/front/unit/data/fixedlayout/"

    setup(function()
        require("commonrequire")
        DocumentRegistry = require("document/documentregistry")
    end)

    -- Open + fully load an EPUB fixture and return the CreDocument.
    local function load(name)
        local doc = DocumentRegistry:openDocument(DATA .. name)
        assert.truthy(doc, "could not open fixture " .. name)
        assert.is_true(doc:loadDocument()) -- full load: builds the DOM, sets the fixed-layout props
        return doc
    end

    it("detects a fully pre-paginated EPUB3 (rendition:layout)", function()
        local doc = load("fxl_epub3_viewport.epub")
        assert.is_true(doc:isFixedLayout())
        assert.are.equal(1, doc:getFixedLayoutMode()) -- DOC_FIXED_LAYOUT_ALL
        doc:close()
    end)

    it("reports a mixed fixed/reflowable EPUB as mixed", function()
        local doc = load("fxl_mixed.epub")
        assert.is_true(doc:isFixedLayout())
        assert.are.equal(2, doc:getFixedLayoutMode()) -- DOC_FIXED_LAYOUT_MIXED
        doc:close()
    end)

    it("detects legacy KF8 fixed-layout metadata and rtl writing mode", function()
        local doc = load("fxl_kf8_legacy.epub")
        assert.is_true(doc:isFixedLayout())
        assert.are.equal("rtl", doc:getPageProgressionDirection())
        doc:close()
    end)

    it("detects fixed-layout declared only in the iBooks display-options file", function()
        local doc = load("fxl_ibooks.epub")
        assert.is_true(doc:isFixedLayout())
        doc:close()
    end)

    it("detects rtl page progression for manga spreads", function()
        local doc = load("fxl_rtl_spread.epub")
        assert.is_true(doc:isFixedLayout())
        assert.are.equal("rtl", doc:getPageProgressionDirection())
        doc:close()
    end)

    it("treats an ordinary reflowable EPUB as not fixed-layout", function()
        local doc = load("reflowable_control.epub")
        assert.is_false(doc:isFixedLayout())
        assert.are.equal(0, doc:getFixedLayoutMode()) -- DOC_FIXED_LAYOUT_NONE
        assert.are.equal("", doc:getPageProgressionDirection())
        doc:close()
    end)
end)
